const pages={home:{title:'项目作战室',desc:'从客户材料到可审批成果，让每一步专业判断都有证据、有版本、有负责人。'},overview:{title:'项目概览',desc:'掌握客户目标、项目阶段与下一步行动。'},materials:{title:'材料中心',desc:'上传、解析并组织项目证据。'},requirements:{title:'需求与场景',desc:'把会议纪要变成可确认的需求基线。'},solution:{title:'方案工作室',desc:'生成有引用、有边界、可评审的解决方案。'},runs:{title:'Agent 运行中心',desc:'实时查看顾问的执行计划与证据链。'},approvals:{title:'成果与审批',desc:'版本化编辑、审批与正式导出。'},delivery:{title:'交付与知识',desc:'把方案转成可执行的交付计划与知识资产。'}};
let current=location.hash.slice(1)||'home';
function nav(){return `<aside class="side"><div class="brand">渡河</div><div class="eyebrow">AI CONSULTING / WORKSPACE</div><nav class="nav"><a class="${current==='home'?'active':''}" href="#home">项目作战室</a><div class="nav-group">项目工作流</div>${[['overview','项目概览'],['materials','01 · 材料中心'],['requirements','02 · 需求与场景'],['solution','03 · 方案工作室'],['runs','04 · Agent 运行中心'],['approvals','05 · 成果与审批'],['delivery','06 · 交付与知识']].map(x=>`<a class="${current===x[0]?'active':''}" href="#${x[0]}">${x[1]}</a>`).join('')}<div class="nav-group">平台</div><a href="#delivery">知识沉淀文档</a></nav><div class="side-foot"><b>证据优先</b><br>每个结论都有来处，每次批准都有记录。</div></aside>`}
function headerBar(){return `<header class="top"><div class="crumb">渡河 / <b>${pages[current].title}</b></div><div class="user"><span>演示工作区</span><i class="avatar">顾</i></div></header>`}
function button(text,action='toast(\'演示动作已触发\')'){return `<button class="primary" onclick="${action}">${text}</button>`}
function home(){return `<div class="hero"><div><div class="kicker">CONSULTING OPERATIONS / 2026</div><h1>项目作战室</h1><p>${pages.home.desc}</p></div>${button('＋ 新建客户项目','openModal()')}</div><div class="line"></div><div class="metrics"><div class="metric"><strong>01</strong><span>活跃项目</span></div><div class="metric"><strong>03</strong><span>待审批成果</span></div><div class="metric"><strong>96%</strong><span>事实引用覆盖</span></div></div><div class="section-head"><h2>进行中的项目</h2><small>1 PROJECT</small></div><div class="cards"><a class="card" href="#overview"><span class="tag">进行中 · 售前方案</span><h3>日企智能客服升级</h3><p>从客户会议纪要到 AI 客服解决方案与提案。</p><div class="progress"><i style="width:70%"></i></div><div class="card-foot"><span>70% 已完成</span><b class="link">继续工作 →</b></div></a><div class="card" style="background:#102221;color:#fff"><span class="tag">LIVE COPILOT</span><h3>顾问正在待命</h3><p style="color:#a9bdb7">上传会议纪要，自动提炼需求与风险。</p>${button('开始顾问演练','location.hash=\'materials\'')}</div></div>`}
function overview(){return `<div class="hero"><div><div class="kicker">PROJECT / 01</div><h1>日企智能客服升级</h1><p>${pages.overview.desc}</p></div>${button('继续下一步','location.hash=\'materials\'')}</div><div class="tabs">${['overview','materials','requirements','solution','approvals','delivery'].map(k=>`<a class="${current===k?'active':''}" href="#${k}">${pages[k].title}</a>`).join('')}</div><div class="grid-3"><div class="panel"><h3>客户目标</h3><p>降低人工客服重复工作，建立日中双语智能服务入口。</p><span class="status">已确认</span></div><div class="panel"><h3>当前阶段</h3><p>方案设计 · 预计本周完成提案初稿。</p><span class="status wait">待审批</span></div><div class="panel"><h3>项目风险</h3><p>知识库权限边界、历史 FAQ 质量待进一步确认。</p><span class="status danger">2 项关注</span></div></div><div class="section-head" style="margin-top:36px"><h2>最近活动</h2></div><div class="timeline"><div class="step"><b>需求分析 Agent 完成</b><small>提炼 12 条证据 · 10 分钟前</small></div><div class="step"><b>方案工作室生成初稿</b><small>已生成 6 个章节 · 32 分钟前</small></div><div class="step wait"><b>等待负责人审批</b><small>商业测算与客户承诺边界 · 现在</small></div></div>`}
function materials(){return `<div class="hero"><div><div class="kicker">SOURCE LIBRARY / 12 ITEMS</div><h1>材料中心</h1><p>${pages.materials.desc}</p></div>${button('＋ 上传材料','document.getElementById(\'file\').click()')}<input id="file" type="file" hidden onchange="toast(\'材料已加入解析队列\')"></div><div class="line"></div><div class="panel" style="border:2px dashed #b8cfc8;text-align:center;padding:48px"><h3>把客户材料拖到这里</h3><p>支持 PDF、DOCX、Markdown、TXT · 自动解析、脱敏与索引</p>${button('选择文件','document.getElementById(\'file\').click()')} <button class="secondary" onclick="toast('已填充脱敏会议纪要样例')">填充演示样例</button></div><div class="section-head" style="margin-top:36px"><h2>项目材料</h2><small>3 DOCUMENTS</small></div><div class="list"><div class="row"><span>AI自动化报告Agent项目｜需求沟通会议纪要.docx</span><span class="status">已索引 · 12 引用</span></div><div class="row"><span>客户现状与客服流程.pdf</span><span class="status">已索引</span></div><div class="row"><span>待确认问题清单.md</span><span class="status wait">需补充</span></div></div><div style="margin-top:24px">${button('开始 AI 需求分析','location.hash=\'runs\'')}</div>`}
function requirements(){return `<div class="hero"><div><div class="kicker">REQUIREMENTS / BASELINE</div><h1>需求与场景</h1><p>${pages.requirements.desc}</p></div>${button('确认需求基线','toast(\'需求基线已确认，方案工作室已解锁\')')}</div><div class="grid-3" style="margin-top:34px"><div class="panel"><h3>客户目标</h3><p>• 提升日中双语响应效率<br>• 降低重复咨询占比<br>• 保留人工升级通道</p></div><div class="panel"><h3>关键痛点</h3><p>• FAQ 分散在多个文档<br>• 新人培训周期长<br>• 无法追踪回答依据</p></div><div class="panel"><h3>信息缺口</h3><p>• 当前咨询量与峰值<br>• 系统接口权限<br>• 合规与数据留存周期</p><span class="status wait">3 项待确认</span></div></div><div class="section-head" style="margin-top:36px"><h2>AI 场景评估</h2><small>3 SCENARIOS</small></div><div class="cards"><div class="card"><span class="tag">优先级 P0 · 92 分</span><h3>智能客服知识助手</h3><p>基于企业 FAQ 的检索增强问答，回答必须附带证据。</p><div class="card-foot"><span class="status">高可行性</span><a class="link" href="#solution">查看方案 →</a></div></div><div class="card"><span class="tag">优先级 P1 · 78 分</span><h3>自动化服务报告</h3><p>按周汇总咨询热点、未解决问题与运营建议。</p><div class="card-foot"><span class="status wait">需评估数据</span><a class="link" href="#solution">查看方案 →</a></div></div></div>`}
function solution(){return `<div class="hero"><div><div class="kicker">SOLUTION STUDIO / DRAFT v0.3</div><h1>方案工作室</h1><p>${pages.solution.desc}</p></div>${button('生成提案初稿','toast(\'提案初稿生成任务已启动\');location.hash=\'runs\'')}</div><div class="tabs"><a class="active">方案章节</a><a onclick="toast('已打开技术架构')">技术架构</a><a onclick="toast('已打开价值测算')">价值测算</a><a onclick="toast('已打开风险台账')">风险台账</a></div><div class="grid-3"><div class="panel"><h3>01 / 背景与目标</h3><p>已完成 · 3 条引用</p><span class="status">有证据</span></div><div class="panel"><h3>02 / 总体方案</h3><p>AI 客服 + 知识库 + 人工升级闭环。</p><span class="status">已生成</span></div><div class="panel"><h3>03 / 实施路线</h3><p>试点 4 周，分两阶段上线。</p><span class="status wait">待确认</span></div></div><div class="panel" style="margin-top:24px"><h3>证据引用预览</h3><p>“现有 FAQ 分散在 4 个部门文档中，新人平均需要 2 周熟悉。”</p><span class="tag">会议纪要 · 第 2 页 · 相似度 0.94</span></div>`}
function runs(){return `<div class="hero"><div><div class="kicker">AGENT RUN / RUN-20260901-001</div><h1>Agent 运行中心</h1><p>${pages.runs.desc}</p></div>${button('重新运行','toast(\'已从上次检查点恢复运行\')')}</div><div class="panel" style="margin-top:34px"><div class="section-head"><h2>需求分析工作流</h2><span class="status">已完成</span></div><div class="timeline"><div class="step"><b>读取并解析材料</b><small>3 个文档 · 12.4 秒</small></div><div class="step"><b>混合检索与重排</b><small>召回 28 条 · 重排 12 条</small></div><div class="step"><b>提炼需求与信息缺口</b><small>生成 12 条事实、3 项待确认</small></div><div class="step"><b>引用质量检查</b><small>覆盖率 96% · 通过</small></div></div></div><div style="margin-top:24px">${button('查看需求结果','location.hash=\'requirements\'')}</div>`}
function approvals(){return `<div class="hero"><div><div class="kicker">REVIEW GATE / 03 PENDING</div><h1>成果与审批</h1><p>${pages.approvals.desc}</p></div>${button('导出正式提案','toast(\'请先完成 3 项审批\')')}</div><div class="line"></div><div class="list"><div class="row"><div><b>需求基线 v1.0</b><br><small>12 条事实 · 3 项假设</small></div><span class="status">已批准</span></div><div class="row"><div><b>方案设计 v0.3</b><br><small>6 个章节 · 18 条引用</small></div><button class="secondary" onclick="toast('已打开方案审阅')">审阅</button></div><div class="row"><div><b>商业价值测算 v0.2</b><br><small>ROI 区间与参数来源</small></div><button class="primary" onclick="toast('审批已通过');this.textContent='已批准'">批准</button></div></div>`}
function delivery(){return `<div class="hero"><div><div class="kicker">DELIVERY & KNOWLEDGE</div><h1>交付与知识</h1><p>${pages.delivery.desc}</p></div>${button('生成交付计划','toast(\'交付计划已生成\')')}</div><div class="grid-3" style="margin-top:34px"><div class="panel"><h3>实施里程碑</h3><p>第 1 周：知识盘点<br>第 2 周：助手配置<br>第 3 周：试点培训<br>第 4 周：上线验收</p></div><div class="panel"><h3>验收标准</h3><p>回答引用覆盖率 ≥95%<br>人工升级成功率 ≥98%<br>关键场景满意度 ≥4.5/5</p></div><div class="panel"><h3>知识候选</h3><p>从已审批成果提取 2 个案例、1 个模板。</p>${button('生成知识候选','toast(\'已生成脱敏知识候选，等待管理员审核\')')}</div></div>`}
function view(){let body={home,overview,materials,requirements,solution,runs,approvals,delivery}[current]?.()||home;document.getElementById('app').innerHTML=`<div class="shell">${nav()}<main class="main">${headerBar()}<section class="content">${body}</section></main></div>`}
