function nav(){return `<aside class="side"><div class="brand">渡河</div><div class="eyebrow">AI CONSULTING / WORKSPACE</div><nav class="nav"><a class="${current==='home'?'active':''}" href="#home">项目作战室</a><div class="nav-group">项目工作流</div>${[['overview','项目概览'],['materials','01 · 材料中心'],['runs','02 · Agent 分析中心'],['requirements','03 · 需求与场景'],['solution','04 · 方案工作室'],['approvals','05 · 成果与审批'],['delivery','06 · 交付与知识']].map(x=>`<a class="${current===x[0]?'active':''}" href="#${x[0]}">${x[1]}</a>`).join('')}<div class="nav-group">平台</div><a href="#delivery">知识沉淀文档</a></nav><div class="side-foot"><b>证据优先</b><br>每个结论都有来处，每次批准都有记录。</div></aside>`}
function requirements(){return `<div class="hero"><div><div class="kicker">REQUIREMENTS / BASELINE</div><h1>需求与场景</h1><p>AI 提炼结果由顾问共同确认，存在疑问时可直接对话追问。</p></div>${button('与 AI / 顾问讨论','openChat()')} ${button('确认需求基线','toast(\'需求基线已确认，方案工作室已解锁\')')}</div><div class="grid-3" style="margin-top:34px"><div class="panel"><h3>客户目标</h3><p>提升日中双语响应效率，降低重复咨询占比，保留人工升级通道。</p><span class="status">12 条事实</span></div><div class="panel"><h3>AI 识别结果</h3><p>已提炼 8 条需求、3 个场景；其中 2 条需要顾问确认。</p><button class="secondary" onclick="openChat()">查看疑问并讨论</button></div><div class="panel"><h3>需求变更</h3><p>最新追加：希望支持客服周报自动生成。</p><span class="status wait">待评估影响</span></div></div><div class="section-head" style="margin-top:36px"><h2>分阶段场景</h2><small>P0 / P1 / P2</small></div><div class="cards"><div class="card"><span class="tag">P0 · 本期必须</span><h3>智能客服知识助手</h3><p>先完成 FAQ 检索问答、引用和人工升级。</p><div class="card-foot"><span class="status">已确认</span><a class="link" href="#solution">纳入方案 →</a></div></div><div class="card"><span class="tag">P1 · 第二阶段</span><h3>自动化服务报告</h3><p>基于已沉淀数据生成周报与运营建议。</p><div class="card-foot"><span class="status wait">待确认</span><a class="link" href="#solution">纳入方案 →</a></div></div></div>`}
function solution(){return `<div class="hero"><div><div class="kicker">SOLUTION STUDIO / ROADMAP</div><h1>方案工作室</h1><p>按 P0 / P1 / P2 分阶段生成方案，任何阶段都可与 AI 协同调整。</p></div>${button('与 AI 协同调整','openChat()')} ${button('生成提案初稿','toast(\'提案初稿生成任务已启动\');location.hash=\'runs\'')}</div><div class="tabs"><a class="active">实施路线</a><a onclick="toast('已打开技术架构')">技术架构</a><a onclick="toast('已打开价值测算')">价值测算</a><a onclick="toast('已打开风险台账')">风险台账</a></div><div class="grid-3"><div class="panel"><span class="tag">P0 · 4 周</span><h3>知识助手试点</h3><p>FAQ 盘点 → RAG 知识库 → 日中问答 → 人工升级。</p><span class="status">建议先做</span></div><div class="panel"><span class="tag">P1 · 6 周</span><h3>服务报告自动化</h3><p>咨询数据汇总、热点分析和周报生成。</p><span class="status wait">依赖 P0</span></div><div class="panel"><span class="tag">P2 · 后续</span><h3>多渠道智能运营</h3><p>接入 CRM、邮件和客户门户，形成运营闭环。</p><span class="status wait">待规划</span></div></div><div class="panel" style="margin-top:24px"><h3>需求变更影响</h3><p>追加“自动化服务报告”将影响 P1 范围，预计增加 2 周实施周期。</p><button class="secondary" onclick="openChat()">让 AI 重新评估计划</button></div>`}
function approvals(){return `<div class="hero"><div><div class="kicker">REVIEW GATE / 03 PENDING</div><h1>成果与审批</h1><p>审阅者可以提问、反馈并打回指定章节，不必整份重做。</p></div>${button('导出正式提案','toast(\'请先完成待审批项\')')}</div><div class="line"></div><div class="list"><div class="row"><div><b>需求基线 v1.0</b><br><small>12 条事实 · 3 项假设</small></div><span class="status">已批准</span></div><div class="row"><div><b>方案设计 v0.3</b><br><small>审阅意见：P1 价值测算缺少数据来源</small></div><div><button class="secondary" onclick="openChat()">问题反馈</button> <button class="primary" onclick="toast('方案已打回，进入协同修改')">打回重改</button></div></div><div class="row"><div><b>商业价值测算 v0.2</b><br><small>ROI 区间与参数来源</small></div><button class="primary" onclick="toast('审批已通过');this.textContent='已批准'">批准</button></div></div>`}
function delivery(){return `<div class="hero"><div><div class="kicker">DELIVERY & KNOWLEDGE</div><h1>交付与知识</h1><p>交付计划由已审批方案生成，顾问可与 AI 共同调整后再执行。</p></div>${button('与 AI 调整计划','openChat()')}</div><div class="grid-3" style="margin-top:34px"><div class="panel"><h3>AI 生成的交付计划</h3><p>第 1 周知识盘点 · 第 2 周助手配置 · 第 3 周培训 · 第 4 周验收</p><button class="secondary" onclick="openChat()">提出修改意见</button></div><div class="panel"><h3>知识沉淀</h3><p>AI 将从已审批成果中筛选案例、模板和实践卡片，自动去除敏感信息。</p><button class="primary" onclick="toast('正在筛选可沉淀知识')">AI 筛选知识</button></div><div class="panel"><h3>上传知识文档</h3><p>上传项目外部的行业资料、方法论和培训文档。</p><input type="file" onchange="toast('知识文档已加入脱敏审核队列')"><div style="margin-top:12px"><span class="status wait">人工审核后发布</span></div></div></div>`}
function openChat(){let e=document.createElement('div');e.className='modal-bg';e.innerHTML=`<div class="modal"><h2>AI / 顾问协同对话</h2><div class="panel"><p><b>AI 顾问：</b>我发现“自动化服务报告”缺少每周咨询量数据，是否先列为 P1 待确认？</p><p><b>你：</b>可以，同时保留人工客服升级通道。</p></div><div class="field"><textarea rows="3" placeholder="输入你的补充、质疑或修改意见"></textarea></div><div class="modal-actions"><button class="secondary" onclick="this.closest('.modal-bg').remove()">关闭</button><button class="primary" onclick="this.closest('.modal-bg').remove();toast('意见已记录，AI 将更新结果')">发送并更新</button></div></div>`;document.body.append(e)}
