function nav(){return `<aside class="side"><div class="brand">渡河</div><div class="eyebrow">AI CONSULTING / WORKSPACE</div><nav class="nav"><a class="${current==='home'?'active':''}" href="#home">项目作战室</a><div class="nav-group">当前项目</div>${[['overview','项目概览'],['materials','01 · 材料中心'],['runs','02 · Agent 分析'],['requirements','03 · 需求与场景'],['solution','04 · 方案工作室'],['approvals','05 · 成果与审批'],['delivery','06 · 项目交付']].map(x=>`<a class="${current===x[0]?'active':''}" href="#${x[0]}">${x[1]}</a>`).join('')}<div class="nav-group">平台资产</div><a class="${current==='knowledge'?'active':''}" href="#knowledge">知识资产库</a><a href="#knowledge">待审核内容</a><div class="nav-group">平台</div><a href="#runs">评测中心</a></nav><div class="side-foot"><b>证据优先</b><br>项目成果可追溯，知识资产可复用。</div></aside>`}
function delivery(){return `<div class="hero"><div><div class="kicker">PROJECT DELIVERY / AFTER APPROVAL</div><h1>项目交付</h1><p>根据已审批方案生成交付计划，顾问可与 AI 协同修改后执行。</p></div>${button('与 AI 调整计划','openChat()')}</div><div class="line"></div><div class="grid-3"><div class="panel"><div class="eyebrow2">AI GENERATED</div><h3>交付计划 v0.1</h3><p>第 1 周知识盘点 · 第 2 周助手配置 · 第 3 周培训 · 第 4 周验收</p><button class="secondary" onclick="openChat()">提出修改意见</button></div><div class="panel"><h3>里程碑与验收</h3><p>当前完成 2 / 4 个里程碑。验收标准已关联 P0 方案。</p><span class="status wait">2 项待确认</span></div><div class="panel"><h3>变更影响</h3><p>最近需求追加将 P1 计划延长 2 周，等待项目负责人确认。</p><span class="status danger">需要决策</span></div></div><div class="section-head"><h2>交付工作包</h2><small>4 WORK PACKAGES</small></div><div class="list"><div class="row"><span>知识库盘点与脱敏</span><span class="status">已完成</span></div><div class="row"><span>智能客服试点配置</span><span class="status wait">进行中</span></div><div class="row"><span>顾问与客服培训</span><span class="status wait">未开始</span></div><div class="row"><span>上线验收与复盘</span><span class="status wait">未开始</span></div></div>`}
function knowledge(){return `<div class="hero"><div><div class="kicker">PLATFORM ASSETS / REUSE</div><h1>知识资产库</h1><p>跨项目沉淀、审核和复用企业方法论、案例与模板。</p></div><input id="kfile" type="file" hidden onchange="toast('文档已进入 AI 脱敏筛选队列')">${button('＋ 上传知识文档','document.getElementById(\'kfile\').click()')}</div><div class="line"></div><div class="grid-3"><div class="panel"><h3>AI 沉淀建议</h3><p>从已审批成果识别出 2 个案例、1 个实施模板。</p><button class="secondary" onclick="toast('已打开脱敏预览')">查看脱敏预览</button></div><div class="panel"><h3>待审核内容</h3><p>4 条候选内容等待知识管理员确认。</p><span class="status wait">待审核</span></div><div class="panel"><h3>资产复用</h3><p>本月被其他项目引用 18 次，复用率持续提升。</p><span class="status">18 次引用</span></div></div><div class="section-head"><h2>已发布资产</h2><small>12 ASSETS</small></div><div class="list"><div class="row"><span>日企客服智能化实施案例</span><span class="status">案例 · 已发布</span></div><div class="row"><span>RAG 知识库盘点模板</span><span class="status">模板 · 已发布</span></div></div>`}
view();
function requirements(){return `<div class="hero"><div><div class="kicker">REQUIREMENTS / COLLABORATION</div><h1>需求与场景</h1><p>AI 提炼、顾问判断、客户反馈在同一个工作区完成。</p></div>${button('确认需求基线','toast(\'需求基线已确认\');location.hash=\'solution\'')}</div><div class="workspace-3"><div class="panel"><div class="eyebrow2">需求基线</div><h3>客户目标</h3><p>提升日中双语响应效率，降低重复咨询占比，保留人工升级通道。</p><h3>AI 识别结果</h3><p>已提炼 8 条需求、3 个场景，其中 2 条需要确认。</p><button class="secondary" onclick="toast('已标记为待确认')">标记疑问</button></div><div><div class="section-head"><h2>分阶段场景</h2><small>P0 / P1 / P2</small></div><div class="stage-card p0"><span class="tag">P0 · 本期必须</span><h3>智能客服知识助手</h3><p>FAQ 检索问答、证据引用、人工升级。</p><span class="status">已确认</span></div><div class="stage-card p1"><span class="tag">P1 · 第二阶段</span><h3>自动化服务报告</h3><p>咨询热点、未解决问题与运营建议。</p><span class="status wait">待数据确认</span></div><div class="stage-card p2"><span class="tag">P2 · 后续探索</span><h3>多渠道智能运营</h3><p>接入 CRM、邮件和客户门户。</p><span class="status wait">未开始</span></div></div><div class="panel copilot"><div class="eyebrow2">LIVE COPILOT</div><h3>AI / 顾问协同</h3><div class="chat"><p><b>AI：</b>“自动化服务报告”缺少每周咨询量，建议列为 P1 待确认。</p><p class="human"><b>你：</b>保留人工升级通道，并先做客服 FAQ 试点。</p></div><textarea rows="3" placeholder="输入补充、质疑或修改意见"></textarea><button class="primary" onclick="toast('意见已记录，AI 将更新需求')">发送并更新</button></div></div>`}
function solution(){return `<div class="hero"><div><div class="kicker">SOLUTION STUDIO / ROADMAP</div><h1>方案工作室</h1><p>按优先级分阶段实施，随需求变更重新评估范围与交付影响。</p></div>${button('让 AI 重算方案','openChat()')} ${button('生成提案初稿','toast(\'提案初稿生成任务已启动\');location.hash=\'runs\'')}</div><div class="solution-layout"><aside class="stage-nav"><b>实施阶段</b><a class="selected">P0 / 试点</a><a>P1 / 扩展</a><a>P2 / 运营</a><hr><a>技术架构</a><a>价值测算</a><a>风险台账</a></aside><div><div class="panel"><span class="tag">P0 · 4 周 · 当前阶段</span><h2>知识助手试点</h2><p>目标：验证 FAQ 检索增强问答、引用质量和人工升级闭环。</p><div class="milestones"><span>01 知识盘点</span><span>02 RAG 配置</span><span>03 试点培训</span><span>04 验收</span></div><button class="secondary" onclick="toast('已打开 P0 章节编辑')">编辑阶段方案</button></div><div class="panel impact"><h3>变更影响</h3><p>追加“自动化服务报告”将进入 P1，预计增加 2 周实施周期，需重新确认预算。</p><span class="status wait">待审批</span></div></div><aside class="panel evidence"><div class="eyebrow2">EVIDENCE</div><h3>证据与风险</h3><p>FAQ 分散在 4 个部门文档中，新人平均需要 2 周熟悉。</p><span class="tag">会议纪要 · 第 2 页 · 0.94</span><h3>风险提示</h3><p>接口权限、数据留存周期尚未确认。</p></aside></div>`}
const render=view;function view(){let body={home,overview,materials,requirements,solution,runs,approvals,delivery,knowledge}[current]?.()||home;document.getElementById('app').innerHTML=`<div class="shell">${nav()}<main class="main">${headerBar()}<section class="content">${body}</section></main></div>`}view();
function home(){return `<div class="hero"><div><div class="kicker">CONSULTING OPERATIONS / 2026</div><h1>项目作战室</h1><p>客户项目全局态势、Agent 执行与审批风险，一屏掌握。</p></div>${button('＋ 新建客户项目','openModal()')}</div><div class="line"></div><div class="metrics"><div class="metric"><strong>01</strong><span>活跃项目</span></div><div class="metric"><strong>03</strong><span>待审批成果</span></div><div class="metric"><strong>07</strong><span>进行中 Agent 任务</span></div><div class="metric"><strong>96%</strong><span>事实引用覆盖</span></div></div><div class="grid-3"><div class="panel"><h3>项目健康度</h3><p>进度 70% · 预算使用 42% · 风险 2 项</p><span class="status">良好</span></div><div class="panel"><h3>本周交付节奏</h3><p>已完成 8 项 · 待确认 3 项 · 已延期 0 项</p><span class="status">按计划</span></div><div class="panel"><h3>知识资产增长</h3><p>本月新增 12 条案例，脱敏审核通过率 91%。</p><span class="status wait">4 条待审核</span></div></div><div class="section-head"><h2>进行中的项目</h2><small>1 PROJECT</small></div><div class="cards"><a class="card" href="#overview"><span class="tag">进行中 · 售前方案</span><h3>日企智能客服升级</h3><p>需求分析 → 分阶段方案 → 审批 → 交付计划</p><div class="progress"><i style="width:70%"></i></div><div class="card-foot"><span>70% 已完成</span><b class="link">继续工作 →</b></div></a><div class="card"><span class="tag">今日待办</span><h3>3 个审批事项</h3><p>方案设计、商业测算和交付范围等待确认。</p><a class="link" href="#approvals">进入审批中心 →</a></div></div>`}
function nav(){return `<aside class="side"><div class="brand">渡河</div><div class="eyebrow">AI CONSULTING / WORKSPACE</div><nav class="nav"><a class="${current==='home'?'active':''}" href="#home">项目作战室</a><div class="nav-group">项目工作流</div>${[['overview','项目概览'],['materials','01 · 材料中心'],['runs','02 · Agent 分析中心'],['requirements','03 · 需求与场景'],['solution','04 · 方案工作室'],['approvals','05 · 成果与审批'],['delivery','06 · 交付与知识']].map(x=>`<a class="${current===x[0]?'active':''}" href="#${x[0]}">${x[1]}</a>`).join('')}<div class="nav-group">知识沉淀</div><a href="#knowledge">知识文档库</a></nav><div class="side-foot"><b>证据优先</b><br>每个结论都有来处，每次批准都有记录。</div></aside>`}
