const oldView=view;function view(){let body={home,overview,materials,requirements,solution,runs,approvals,delivery,knowledge}[current]?.()||home;document.getElementById('app').innerHTML=`<div class="shell">${nav()}<main class="main">${headerBar()}<section class="content">${body}</section></main></div>`}view();
function toast(s){let e=document.createElement('div');e.className='toast';e.textContent=s;document.body.append(e);setTimeout(()=>e.remove(),2200)}function openModal(){let e=document.createElement('div');e.className='modal-bg';e.innerHTML=`<div class="modal"><h2>新建客户项目</h2><div class="field"><label>客户名称</label><input placeholder="例如：日企智能客服升级"></div><div class="field"><label>项目目标</label><textarea rows="3" placeholder="描述客户希望解决的问题"></textarea></div><div class="modal-actions"><button class="secondary" onclick="this.closest('.modal-bg').remove()">取消</button><button class="primary" onclick="this.closest('.modal-bg').remove();toast('项目已创建');location.hash='overview'">创建项目</button></div></div>`;document.body.append(e)}window.addEventListener('hashchange',()=>{current=location.hash.slice(1)||'home';view()});view();
